@extends('layouts.app',['title'=>'Access Control']) @section('content')<div class="heading"><div><div class="eyebrow">Identity & least privilege</div><h1>Users, roles & permissions</h1></div><span class="badge">{{$users->count()}} accounts</span></div>@if(session('success'))<div style="padding:14px;background:#e8f8ee;color:#237a46;border-radius:11px;margin-bottom:16px">{{session('success')}}</div>@endif @if($errors->any())<div style="padding:14px;background:#fff0f0;color:#b43b4b;border-radius:11px;margin-bottom:16px">{{$errors->first()}}</div>@endif<div class="grid"><form method="post" action="{{route('access.users.store')}}" class="card panel">@csrf<div class="panel-title"><h3>Create staff account</h3></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><input name="name" required placeholder="Full name" style="padding:10px"><input name="email" type="email" required placeholder="Email" style="padding:10px"><input name="phone" placeholder="+923001234567" style="padding:10px"><select name="role_id" style="padding:10px">@foreach($roles as $role)<option value="{{$role->id}}">{{$role->label}}</option>@endforeach</select><input name="password" type="password" required placeholder="Temporary password" style="padding:10px"><input name="password_confirmation" type="password" required placeholder="Confirm password" style="padding:10px"></div><button class="button" style="margin-top:14px">Create account</button></form><form method="post" action="{{route('access.roles.store')}}" class="card panel">@csrf<div class="panel-title"><h3>Create custom role</h3></div><input name="label" required placeholder="Role label" style="padding:10px;width:48%"><input name="name" required placeholder="role_code" style="padding:10px;width:48%"><div style="max-height:170px;overflow:auto;margin-top:12px">@foreach($permissions as $module=>$items)<strong>{{$module}}</strong><div style="display:flex;flex-wrap:wrap;gap:8px;margin:6px 0 12px">@foreach($items as $permission)<label><input type="checkbox" name="permission_ids[]" value="{{$permission->id}}"> {{$permission->label}}</label>@endforeach</div>@endforeach</div><button class="button">Create role</button></form></div><div class="card panel" style="margin-top:18px"><div class="panel-title"><h3>Staff access</h3></div>@foreach($users as $user)<form method="post" action="{{route('access.users.update',$user)}}" style="display:grid;grid-template-columns:1.4fr 2fr .7fr auto;gap:12px;align-items:center;padding:13px;border-top:1px solid #edf0f5">@csrf @method('put')<div><strong>{{$user->name}}</strong><div class="eyebrow">{{$user->email}}</div></div><div>@foreach($roles as $role)<label style="margin-right:8px"><input type="checkbox" name="role_ids[]" value="{{$role->id}}" @checked($user->roles->contains($role))> {{$role->label}}</label>@endforeach</div><select name="status" style="padding:8px"><option value="active" @selected($user->status==='active')>Active</option><option value="suspended" @selected($user->status==='suspended')>Suspended</option></select><button class="button" style="padding:8px 10px">Save</button></form>@endforeach</div><div class="card panel" style="margin-top:18px"><div class="panel-title"><h3>Role permission matrix</h3></div>@foreach($roles as $role)<form method="post" action="{{route('access.roles.update',$role)}}" style="padding:14px;border-top:1px solid #edf0f5">@csrf @method('put')<strong>{{$role->label}}</strong> <span class="badge">{{$role->permissions_count}} permissions</span><div style="display:flex;flex-wrap:wrap;gap:8px;margin:10px 0">@foreach($permissions->flatten() as $permission)<label><input type="checkbox" name="permission_ids[]" value="{{$permission->id}}" @checked($role->permissions->contains($permission))> {{$permission->label}}</label>@endforeach</div><button class="button" style="padding:7px 10px">Update permissions</button></form>@endforeach</div>@endsection
